package android.app;import android.content.*;public class Activity extends Context{public int binds,unbinds,flags;public boolean accept=true,throwsBind;public ServiceConnection connection;public Intent intent;public int getTaskId(){return 1;}public boolean bindService(Intent i,ServiceConnection c,int f){binds++;connection=c;flags=f;intent=i;if(throwsBind)throw new SecurityException("fixture");return accept;}public void unbindService(ServiceConnection c){unbinds++;}public void connect(Service service){connection.onServiceConnected(new ComponentName(),service.onBind(intent));}}
